CREATE OR REPLACE FUNCTION public.queue_abandoned_private_uploads(_cutoff timestamptz) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE removed integer; BEGIN WITH gone AS (DELETE FROM public.talent_private_documents WHERE id IN (SELECT id FROM public.talent_private_documents WHERE validated_at IS NULL AND validation_pending_since < LEAST(_cutoff,now()-interval '24 hours') ORDER BY validation_pending_since LIMIT 500 FOR UPDATE SKIP LOCKED) AND validated_at IS NULL RETURNING storage_path), queued AS (INSERT INTO public.document_storage_purge_queue(bucket,path) SELECT 'talent-private-documents',storage_path FROM gone WHERE storage_path IS NOT NULL RETURNING id) SELECT count(*) INTO removed FROM queued; RETURN removed; END $$;
REVOKE ALL ON FUNCTION public.queue_abandoned_private_uploads(timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.queue_abandoned_private_uploads(timestamptz) TO service_role;
ALTER TABLE public.talent_private_documents ADD COLUMN IF NOT EXISTS download_only boolean NOT NULL DEFAULT false;